<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { notificationEvents, normalizeNotificationRules, marketingEvent, eventLabel } from '../../utils/whatsapp-notifications'
const props=defineProps<{companyId:string;connected:boolean}>()
const emit=defineEmits<{busy:[value:boolean]}>()
const scope=useCompanyScope(),settings=ref<any>(null),busy=ref(false),error=ref(''),notice=ref('')
const templates=ref<any[]>([]),contacts=ref<any[]>([]),queue=ref<any[]>([]),installations=ref<any[]>([])
const search=ref(''),installationSearch=ref(''),section=ref('rules'),contact=ref<any>(null),appointment=ref<any>(null)
const groups=computed(()=>[...new Set(notificationEvents.map(e=>e[2]))])
const api=(action:string,method:any='GET',body?:any,query?:any)=>$fetch<any>('/api/whatsapp-notifications/'+action,{method,body,query,headers:{'x-company-id':props.companyId},retry:0})
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;scope.busy.value=true;emit('busy',true);error.value='';notice.value='';try{await work()}catch(e:any){error.value=e?.data?.statusMessage||e?.statusMessage||e?.message||'Could not update notifications.'}finally{busy.value=false;scope.busy.value=false;emit('busy',false)}}
async function load(){settings.value=await api('settings');if(settings.value.ready){queue.value=await api('queue');if(props.connected){let after='';const seen=new Set<string>();templates.value=[];do{const page=await $fetch<any>('/api/connect/whatsapp/templates',{query:after?{after}:undefined,headers:{'x-company-id':props.companyId},retry:0});templates.value.push(...page.data||[]);after=page.after||'';if(seen.has(after))break;seen.add(after)}while(after)}}}
async function save(){settings.value=await api('settings','PUT',{enabled:settings.value.enabled,rules:settings.value.rules});notice.value='Notification rules saved.'}
async function loadContacts(){contacts.value=await api('contacts','GET',undefined,{q:search.value})}
async function loadInstallations(){installations.value=await api('installations','GET',undefined,{q:installationSearch.value})}
async function openSection(value:string){section.value=value;await run(async()=>{if(value==='contacts')await loadContacts();if(value==='installations')await loadInstallations();if(value==='activity')queue.value=await api('queue')})}
function editContact(row:any){contact.value={clientId:row.id,name:row.name,recipient:row.recipient||'',serviceConsent:!!row.service_consent,marketingConsent:!!row.marketing_consent,evidence:row.evidence||''}}
async function saveContact(){await api('contacts','POST',contact.value);contact.value=null;await loadContacts();notice.value='Client messaging preferences saved.'}
function editAppointment(row:any){const date=row.appointment_on?new Date(row.appointment_on):null;const local=date?new Date(+date-date.getTimezoneOffset()*60000).toISOString().slice(0,16):'';appointment.value={customerProductId:row.id,name:row.reference+' - '+row.name,appointmentOn:local,technician:row.technician||'',status:'SCHEDULED'}}
async function saveAppointment(){await api('installations','POST',{...appointment.value,appointmentOn:new Date(appointment.value.appointmentOn).toISOString()});appointment.value=null;await loadInstallations();notice.value='Installation appointment saved. Record completion in the product’s service history.'}
async function cancelAppointment(row:any){await api('installations','POST',{customerProductId:row.id,status:'CANCELLED',technician:row.technician||''});await loadInstallations();notice.value='Installation appointment cancelled.'}
function applyTemplate(id:string,marketing:boolean){for(const [key]of notificationEvents)if(marketingEvent(key)===marketing)settings.value.rules[key].templateId=id}
async function createTemplates(){
  for(const category of ['UTILITY','MARKETING']){
    const name=category==='UTILITY'?'markit_customer_update':'markit_service_feedback'
    if(!templates.value.some(t=>t.name===name&&t.language==='en_US'))await $fetch('/api/connect/whatsapp/templates',{method:'POST',headers:{'x-company-id':props.companyId},retry:0,body:{name,language:'en_US',category,components:[{type:'BODY',text:'Hello {{1}}, {{2}} update: {{3}}. {{4}}',example:{body_text:[['Alex','Your store','Service appointment','Your visit is booked for 20 November at 10 AM.']]}}]}})
  }
  await load();notice.value='Starter templates submitted. Refresh after Meta approves them, then select them below.'
}
async function process(){await api('process','POST',{});queue.value=await api('queue');notice.value='Notification run completed. Review the delivery activity below.';section.value='activity'}
const deliveryState=(row:any)=>row.status==='ACCEPTED'?(row.delivery_status||row.status):row.status
onMounted(()=>run(load));onBeforeUnmount(()=>{scope.busy.value=false})
</script>
<template>
  <div class="space-y-5">
    <div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="text-lg font-semibold">Client notifications</h2><p class="mt-1 text-sm text-gray-500">Sales, delivery, coverage, service appointments and payment updates from this company.</p></div><button class="action" :disabled="busy" @click="run(load)">Refresh</button></div>
    <p v-if="!settings" role="status">Loading notification settings…</p>
    <p v-if="error" role="alert" class="rounded-lg bg-red-50 p-3 text-sm text-red-800">{{error}}</p><p v-if="notice" role="status" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">{{notice}}</p>
    <div v-if="settings&&!settings.ready" class="panel"><h3 class="font-medium">Notification setup is pending</h3><p class="mt-2 text-sm text-gray-500">Your operator needs to install the prepared customer notification update before automation can be enabled.</p></div>
    <template v-if="settings?.ready">
      <nav aria-label="Notification settings" class="flex flex-wrap gap-2"><button v-for="item in [['rules','Events and templates'],['contacts','Client permissions'],['installations','Installation appointments'],['activity','Delivery activity']]" :key="item[0]" class="action" :aria-pressed="section===item[0]" :disabled="busy" @click="openSection(item[0])">{{item[1]}}</button></nav>
      <form v-if="section==='rules'" class="space-y-5" @submit.prevent="run(save)">
        <fieldset :disabled="busy" class="panel space-y-4"><label class="flex items-center gap-2 font-medium"><input v-model="settings.enabled" type="checkbox" /> Enable automatic client notifications</label><p class="text-sm text-gray-500">Updates are checked every five minutes. Existing sales and completed work are retained as a baseline when enabling; upcoming due reminders remain eligible. Each client’s messaging permissions are checked before sending.</p><p v-if="!connected" class="text-sm text-amber-700">Connect this company’s WhatsApp number first.</p>
          <div class="flex flex-wrap gap-3"><button type="button" class="action" :disabled="!connected" @click="run(createTemplates)">Create starter templates</button><select class="field max-w-sm" aria-label="Default update template" @change="applyTemplate(($event.target as HTMLSelectElement).value,false)"><option value="">Apply an approved update template to all events</option><option v-for="t in templates.filter(t=>t.status==='APPROVED'&&t.category==='UTILITY')" :key="t.id" :value="t.id">{{t.name}} ({{t.language}})</option></select></div>
          <p class="text-xs text-gray-500">Templates use four body values in order: client name, company name, update title and details. Feedback uses a Marketing template and separate client permission.</p>
        </fieldset>
        <fieldset v-for="group in groups" :key="group" :disabled="busy" class="panel"><legend class="px-2 font-semibold">{{group}}</legend><div class="space-y-3"><div v-for="event in notificationEvents.filter(e=>e[2]===group)" :key="event[0]" class="grid items-center gap-2 sm:grid-cols-2"><label class="flex items-center gap-2 text-sm"><input v-model="settings.rules[event[0]].enabled" type="checkbox" />{{event[1]}}</label><select v-model="settings.rules[event[0]].templateId" class="field" :aria-label="event[1]+' template'"><option value="">Choose approved template</option><option v-for="t in templates.filter(t=>t.status==='APPROVED'&&(!marketingEvent(event[0])||t.category==='MARKETING'))" :key="t.id" :value="t.id">{{t.name}} · {{t.language}} · {{t.category}}</option></select></div></div></fieldset>
        <div class="flex flex-wrap gap-3"><button class="action primary" type="submit" :disabled="busy||settings.enabled&&!connected">Save notifications</button><button class="action" type="button" :disabled="busy||!settings.enabled||!connected" @click="run(process)">Process notifications now</button></div>
      </form>
      <section v-if="section==='contacts'" class="space-y-4"><form class="flex gap-2" @submit.prevent="run(loadContacts)"><input v-model="search" class="field" placeholder="Search client name or phone" aria-label="Search notification clients"/><button class="action" :disabled="busy">Search</button></form>
        <form v-if="contact" class="panel space-y-3" @submit.prevent="run(saveContact)"><h3 class="font-semibold">{{contact.name}}</h3><label class="label">WhatsApp number, including country code<input v-model="contact.recipient" class="field" required placeholder="919876543210" /></label><label class="flex items-center gap-2 text-sm"><input v-model="contact.serviceConsent" type="checkbox"/> Client permits purchase, delivery, service and payment updates</label><label class="flex items-center gap-2 text-sm"><input v-model="contact.marketingConsent" type="checkbox"/> Client permits feedback and marketing messages</label><label class="label">Permission record / source<textarea v-model="contact.evidence" class="field" required maxlength="1000" placeholder="For example: client requested updates at the counter, with date" /></label><p class="text-xs text-gray-500">A STOP reply withdraws both permissions. A change to the client’s saved phone requires a fresh permission record.</p><div class="flex gap-2"><button class="action primary" :disabled="busy">Save client permissions</button><button class="action" type="button" :disabled="busy" @click="contact=null">Close</button></div></form>
        <div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Client</th><th>WhatsApp</th><th>Service</th><th>Marketing</th><th></th></tr></thead><tbody><tr v-for="row in contacts" :key="row.id"><td>{{row.name}}<p class="text-xs text-gray-500">{{row.phone}}</p></td><td>{{row.recipient||'Not recorded'}}<p v-if="row.recipient&&row.phone_changed" class="text-xs text-amber-700">Phone changed: renew permission</p></td><td>{{row.service_consent?'Allowed':'Off'}}</td><td>{{row.marketing_consent?'Allowed':'Off'}}</td><td><button class="action" :disabled="busy" @click="editContact(row)">Edit permissions</button></td></tr></tbody></table><p v-if="!contacts.length" class="p-4 text-sm text-gray-500">No clients match this search.</p></div>
      </section>
      <section v-if="section==='installations'" class="space-y-4"><p class="text-sm text-gray-500">Book or reschedule installation for a registered product. Complete installation by recording its date in the product’s after-sales history.</p><form class="flex gap-2" @submit.prevent="run(loadInstallations)"><input v-model="installationSearch" class="field" aria-label="Search installations" placeholder="Search client, product or reference"/><button class="action" :disabled="busy">Search</button></form>
        <form v-if="appointment" class="panel space-y-3" @submit.prevent="run(saveAppointment)"><h3 class="font-medium">{{appointment.name}}</h3><label class="label">Installation date and time<input v-model="appointment.appointmentOn" class="field" type="datetime-local" required/></label><label class="label">Technician<input v-model="appointment.technician" class="field" maxlength="200"/></label><div class="flex gap-2"><button class="action primary" :disabled="busy">Save installation appointment</button><button type="button" class="action" :disabled="busy" @click="appointment=null">Close</button></div></form>
        <div class="space-y-3"><article v-for="row in installations" :key="row.id" class="panel flex flex-wrap items-center justify-between gap-3"><div><p class="font-medium">{{row.reference}} · {{row.name}}</p><p class="text-sm text-gray-500">{{row.client_name}} · {{row.appointment_on?new Date(row.appointment_on).toLocaleString():'No appointment'}} · {{row.status||'Not booked'}}</p></div><div class="flex gap-2"><button class="action" :disabled="busy" @click="editAppointment(row)">Book / reschedule</button><button v-if="row.status==='SCHEDULED'" class="action" :disabled="busy" @click="run(()=>cancelAppointment(row))">Cancel appointment</button></div></article></div>
      </section>
      <section v-if="section==='activity'" class="space-y-4"><div class="flex flex-wrap gap-3"><button class="action" :disabled="busy||!connected||!settings.enabled" @click="run(process)">Process notifications now</button><p class="text-sm text-gray-500">Accepted means WhatsApp received the request. Sent, Delivered and Read come from delivery receipts. Unconfirmed sends need investigation before sending again.</p></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Client</th><th>Update</th><th>Scheduled</th><th>State</th><th>Details</th></tr></thead><tbody><tr v-for="row in queue" :key="row.id"><td>{{row.client_name}}</td><td>{{eventLabel(row.event_type)}}</td><td>{{new Date(row.available_at).toLocaleString()}}</td><td>{{deliveryState(row)}}</td><td>{{row.reason}}<p class="text-xs text-gray-500">{{row.recipient}} {{row.meta_id}}</p></td></tr></tbody></table><p v-if="!queue.length" class="p-5 text-sm text-gray-500">No notifications queued yet.</p></div></section>
    </template>
  </div>
</template>
<style scoped>
.panel{@apply rounded-xl border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-900;}
.action{@apply rounded-lg border border-gray-300 px-3 py-2 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600;}
.primary{@apply border-emerald-600 bg-emerald-600 text-white;}
.field{@apply block w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm dark:border-gray-600 dark:bg-gray-900;}
.label{@apply block space-y-1 text-sm font-medium;}
td,th{@apply border-b border-gray-200 px-3 py-3 align-top dark:border-gray-700;}
</style>
